validator:
function validate(input) {
  const [{ Teams = [] }] = input;
  const names = new Set();
  for (const [name] of Teams) {
    if (name === null || name === '') return 'Every team needs a name.';
    // Names compare without case, as in MySQL's default collation.
    const key = name.toLowerCase();
    if (names.has(key)) return `Team ${name} appears twice in Teams.`;
    names.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 7) : 100;
  const base = ['Leetcode FC', 'Ahly SC', 'Real Madrid', 'Al Ittihad', 'Ajax', 'Benfica', 'Celtic', 'Porto'];
  const names = small ? base.slice() : Array.from({ length: count }, (_, i) => `Club ${i + 1}`);
  for (let i = names.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [names[i], names[j]] = [names[j], names[i]]; }
  return [{ Teams: names.slice(0, count).map(name => [name]) }];
}
